///  Pointing and Power Scenario - a scenario, and the telemetry a run of it
///  produced.
public struct PPS: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$PPS" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: PPS.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let RUN_ID: VOffset = 4
    static let CREATED_AT_MS: VOffset = 6
    static let PROVIDER: VOffset = 8
    static let SCENARIO: VOffset = 10
    static let STATUS: VOffset = 12
    static let ERROR_CODE: VOffset = 14
    static let ERROR_MESSAGE: VOffset = 16
    static let PRODUCTS: VOffset = 18
    static let ASSUMPTIONS: VOffset = 20
    static let TELEMETRY: VOffset = 22
  }

  ///  Identifier of the run; empty = not assigned.
  public var RUN_ID: String? { let o = _accessor.offset(VT.RUN_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var RUN_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.RUN_ID) }
  ///  Unix milliseconds the run was made.
  public var CREATED_AT_MS: Int64 { let o = _accessor.offset(VT.CREATED_AT_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  ///  Identifier of the simulator that ran it.
  public var PROVIDER: String? { let o = _accessor.offset(VT.PROVIDER); return o == 0 ? nil : _accessor.string(at: o) }
  public var PROVIDERSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PROVIDER) }
  public var SCENARIO: ppsScenario? { let o = _accessor.offset(VT.SCENARIO); return o == 0 ? nil : ppsScenario(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var STATUS: ppsStatus { let o = _accessor.offset(VT.STATUS); return o == 0 ? .pending : ppsStatus(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .pending }
  ///  Stable machine-readable reason for InvalidRequest or Failed.
  public var ERROR_CODE: String? { let o = _accessor.offset(VT.ERROR_CODE); return o == 0 ? nil : _accessor.string(at: o) }
  public var ERROR_CODESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.ERROR_CODE) }
  public var ERROR_MESSAGE: String? { let o = _accessor.offset(VT.ERROR_MESSAGE); return o == 0 ? nil : _accessor.string(at: o) }
  public var ERROR_MESSAGESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.ERROR_MESSAGE) }
  ///  Products the telemetry carries.
  public var PRODUCTS: FlatbufferVector<ppsProduct> { return _accessor.vector(at: VT.PRODUCTS, byteSize: 1) }
  ///  Modelling assumptions and simplifications of the run, as text.
  public var ASSUMPTIONS: FlatbufferVector<String?> { return _accessor.vector(at: VT.ASSUMPTIONS, byteSize: 4) }
  public var TELEMETRY: ppsTelemetry? { let o = _accessor.offset(VT.TELEMETRY); return o == 0 ? nil : ppsTelemetry(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startPPS(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 10) }
  public static func add(RUN_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RUN_ID, at: VT.RUN_ID) }
  public static func add(CREATED_AT_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CREATED_AT_MS, def: 0, at: VT.CREATED_AT_MS) }
  public static func add(PROVIDER: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROVIDER, at: VT.PROVIDER) }
  public static func add(SCENARIO: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SCENARIO, at: VT.SCENARIO) }
  public static func add(STATUS: ppsStatus, _ fbb: inout FlatBufferBuilder) { fbb.add(element: STATUS.rawValue, def: 0, at: VT.STATUS) }
  public static func add(ERROR_CODE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ERROR_CODE, at: VT.ERROR_CODE) }
  public static func add(ERROR_MESSAGE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ERROR_MESSAGE, at: VT.ERROR_MESSAGE) }
  public static func addVectorOf(PRODUCTS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PRODUCTS, at: VT.PRODUCTS) }
  public static func addVectorOf(ASSUMPTIONS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ASSUMPTIONS, at: VT.ASSUMPTIONS) }
  public static func add(TELEMETRY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TELEMETRY, at: VT.TELEMETRY) }
  public static func endPPS(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createPPS(
    _ fbb: inout FlatBufferBuilder,
    RUN_IDOffset RUN_ID: Offset = Offset(),
    CREATED_AT_MS: Int64 = 0,
    PROVIDEROffset PROVIDER: Offset = Offset(),
    SCENARIOOffset SCENARIO: Offset = Offset(),
    STATUS: ppsStatus = .pending,
    ERROR_CODEOffset ERROR_CODE: Offset = Offset(),
    ERROR_MESSAGEOffset ERROR_MESSAGE: Offset = Offset(),
    PRODUCTSVectorOffset PRODUCTS: Offset = Offset(),
    ASSUMPTIONSVectorOffset ASSUMPTIONS: Offset = Offset(),
    TELEMETRYOffset TELEMETRY: Offset = Offset()
  ) -> Offset {
    let __start = PPS.startPPS(&fbb)
    PPS.add(RUN_ID: RUN_ID, &fbb)
    PPS.add(CREATED_AT_MS: CREATED_AT_MS, &fbb)
    PPS.add(PROVIDER: PROVIDER, &fbb)
    PPS.add(SCENARIO: SCENARIO, &fbb)
    PPS.add(STATUS: STATUS, &fbb)
    PPS.add(ERROR_CODE: ERROR_CODE, &fbb)
    PPS.add(ERROR_MESSAGE: ERROR_MESSAGE, &fbb)
    PPS.addVectorOf(PRODUCTS: PRODUCTS, &fbb)
    PPS.addVectorOf(ASSUMPTIONS: ASSUMPTIONS, &fbb)
    PPS.add(TELEMETRY: TELEMETRY, &fbb)
    return PPS.endPPS(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.RUN_ID, fieldName: "RUN_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CREATED_AT_MS, fieldName: "CREATED_AT_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PROVIDER, fieldName: "PROVIDER", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SCENARIO, fieldName: "SCENARIO", required: false, type: ForwardOffset<ppsScenario>.self)
    try _v.visit(field: VT.STATUS, fieldName: "STATUS", required: false, type: ppsStatus.self)
    try _v.visit(field: VT.ERROR_CODE, fieldName: "ERROR_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ERROR_MESSAGE, fieldName: "ERROR_MESSAGE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PRODUCTS, fieldName: "PRODUCTS", required: false, type: ForwardOffset<Vector<ppsProduct, ppsProduct>>.self)
    try _v.visit(field: VT.ASSUMPTIONS, fieldName: "ASSUMPTIONS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.TELEMETRY, fieldName: "TELEMETRY", required: false, type: ForwardOffset<ppsTelemetry>.self)
    _v.finish()
  }
}
